"""Build the review gallery and overview board for the week alternatives."""
from html import escape
import json
from pathlib import Path
from PIL import Image, ImageDraw, ImageFont

root=Path(__file__).resolve().parents[1]
screens=json.loads((root/'manifest.json').read_text())['screens']
style='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f7f1e7;color:#343c31;font:16px/1.5 -apple-system,BlinkMacSystemFont,sans-serif}main{max-width:1440px;margin:auto;padding:44px 28px 70px}a{color:#3c654c;text-underline-offset:3px}h1,h2,h3{font-family:ui-rounded,-apple-system,sans-serif;line-height:1.14}h1{font-size:clamp(36px,5vw,56px);letter-spacing:-1.4px;margin:18px 0}h2{font-size:29px;letter-spacing:-.5px}h3{font-size:20px;letter-spacing:-.3px;margin:0 0 10px}.eyebrow{color:#646357;font-size:12px;letter-spacing:.1em;text-transform:uppercase;font-weight:600}.lead{font-size:20px;max-width:850px}.note{font-size:14px;color:#646357;max-width:900px}.links{display:flex;gap:18px;flex-wrap:wrap;margin:24px 0;font-size:14px}.recommendation{padding:20px 24px;border-radius:22px;background:#e6eddd;margin:28px 0 36px;max-width:950px}.recommendation strong{display:block;font-size:18px;margin-bottom:6px}.recommendation p{margin:0}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:18px;align-items:start}.card{background:#fffcf6;border:1px solid #e6dfd2;border-radius:23px;padding:16px;min-width:0}.card.recommended{border:2px solid #3c654c;padding:15px}.card p{font-size:14px;color:#646357;line-height:1.5;margin:10px 0}.card img{width:100%;height:auto;display:block;border-radius:14px;margin:20px 0 16px}.card .dimensions{font-size:12px;color:#646357;margin:12px 0}.card .notes{font-size:13px;color:#343c31;border-top:1px solid #e6dfd2;padding-top:12px;margin-top:16px}.card .source{font-size:13px}.badge{display:inline-block;background:#e6eddd;border-radius:12px;padding:4px 9px;font-size:11px;font-weight:650;color:#3c654c;margin-bottom:12px}.extra{margin-top:38px}.extra>summary{font-size:26px;font-family:ui-rounded,-apple-system,sans-serif;font-weight:650;cursor:pointer;min-height:44px}.extra .grid{margin-top:20px;grid-template-columns:repeat(3,minmax(0,1fr))}.extra .card img{max-width:330px;margin-left:auto;margin-right:auto}.extra p{color:#646357}.tradeoffs{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:35px}.tradeoff{border-top:1px solid #d0c9bb;padding:18px 0}.tradeoff p{font-size:14px;color:#646357}footer{margin-top:40px;padding-top:24px;border-top:1px solid #e6dfd2;font-size:14px;color:#646357}a:focus-visible,summary:focus-visible{outline:3px solid #3c654c;outline-offset:4px}@media(max-width:1100px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.extra .grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:620px){main{padding:28px 18px 60px}.grid,.extra .grid,.tradeoffs{grid-template-columns:1fr}.card img{max-width:350px;margin-left:auto;margin-right:auto}.lead{font-size:18px}.recommendation{padding:18px}h2{font-size:26px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}'''
parts=[f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Family Hub · Week view options</title><style>{style}</style><main><header><div class="eyebrow">Family Hub · Warm Sage Cosier · iPhone</div><h1>A more useful Week view</h1><p class="lead">Compare three alternatives with the existing layout. Each uses the same sample dates, event times, and palette.</p><div class="links"><a href="../calendar-widgets/index.html">Calendar and widgets</a><a href="overview.png">Open the comparison board</a><a href="README.md">Read the interaction notes</a><a href="validation.json">Validation</a></div><p class="note">Static proposals only. The baseline is a drawing of the existing layout, not a new simulator capture. These options explore changes beyond the earlier Calendar restyle.</p></header><aside class="recommendation"><strong>Selected: A · Compact all-day</strong><p>Keep the seven-day timeline. Use one compact row for all-day items. Tap its count to inspect the full list.</p></aside><h2>Compare the layouts</h2><div class="grid" id="compare">''']
def card(screen):
    recommended=screen['id']=='week-compact'
    return f'''<article class="card {'recommended' if recommended else ''}" id="{screen['id']}">{'<span class="badge">Selected</span>' if recommended else ''}<h3>{escape(screen['title'])}</h3><p>{escape(screen['description'])}</p><a href="{screen['file']}"><img width="{screen['width']}" height="{screen['height']}" src="{screen['file']}" alt="{escape(screen['title'])} mockup" loading="lazy"></a><p class="dimensions">{screen['width']} × {screen['height']} points · PNG at 3×</p><a class="source" href="source/mockups.html?screen=calendar-week&amp;variant={screen['id']}">Open editable layout</a><p class="notes">{escape(screen['notes'])}</p></article>'''
parts.extend(card(screen) for screen in screens if screen['group']=='Compare')
parts.append('''</div><div class="tradeoffs"><div class="tradeoff"><h3>A · The smallest change</h3><p>More room for timed events. Seven-day labels remain narrow.</p></div><div class="tradeoff"><h3>B · Overview and detail</h3><p>Readable event names with the full week above. Each pane needs its own scroll position.</p></div><div class="tradeoff"><h3>C · A readable grid</h3><p>Wider day columns. More horizontal movement to see the full week.</p></div></div>''')
for group,title,description in [('Interactions','How the interactions fit','All-day items, Day view, the layout menu, and the initial time position.'),('Adaptations','Selected layout: dark, small iPhone, and large text','Keep the same hierarchy across appearances and screen sizes. Large text uses the existing agenda fallback.')]:
    parts.append(f'<details class="extra" id="{group.lower()}"><summary>{title}</summary><p>{description}</p><div class="grid">')
    parts.extend(card(screen) for screen in screens if screen['group']==group)
    parts.append('</div></details>')
parts.append('''<footer><p>Option B uses date taps to select an agenda. Open day is a separate action. Options A and C can use a date tap to open Day directly.</p><p>Calendar event colours remain distinct. Meals and chores remain in the all-day list. No arrival margin appears.</p><a href="README.md">Design scope, interactions, and implementation boundaries</a></footer></main></html>''')
(root/'index.html').write_text(''.join(parts))
font_path='/System/Library/Fonts/Supplemental/Arial.ttf'
def font(size): return ImageFont.truetype(font_path,size)
board=Image.new('RGB',(1800,1170),'#eae4d8');draw=ImageDraw.Draw(board)
draw.text((52,30),'Calendar Week · Three alternatives',font=font(38),fill='#343c31')
draw.text((52,86),'The same events, shown with different priorities.',font=font(22),fill='#646357')
labels=[('week-baseline','Existing layout'),('week-compact','A · Compact all-day'),('week-agenda','B · Week + agenda'),('week-three-days','C · Three days')]
for index,(name,label) in enumerate(labels):
    left=52+index*430
    draw.text((left,140),label,font=font(23),fill='#3c654c')
    if name=='week-compact':draw.text((left,173),'Selected',font=font(16),fill='#3c654c')
    picture=Image.open(root/'images'/(name+'.png')).convert('RGBA')
    picture=picture.resize((402,874),Image.Resampling.LANCZOS)
    board.paste(picture,(left,207),picture)
draw.text((52,1120),'Static iPhone proposals · No app changes · Full-size images and interaction states in the gallery',font=font(18),fill='#646357')
board.save(root/'overview.png')
print(f'Built the comparison and {len(screens)} screen cards.')
